import mri from "mri";

import * as pkg from "../package.json";

// Slice Machine is deprecated: every run prints the notice, then continues.
// Projects that have read it can set PRISMIC_IGNORE_SLICE_MACHINE_DEPRECATION.
if (!process.env.PRISMIC_IGNORE_SLICE_MACHINE_DEPRECATION) {
	console.error(
		`Slice Machine is deprecated. This project still works, but Slice Machine is no longer updated.

New projects use the Type Builder, and this project can move to it with the Prismic CLI:

  npx prismic init

Working with an AI agent? Install the Prismic skill so it knows the current workflow:

  npx skills add --global --yes prismicio/skills

Docs: https://prismic.io/docs/slice-machine#migrate-to-the-type-builder
Set PRISMIC_IGNORE_SLICE_MACHINE_DEPRECATION=1 to hide this notice.
`,
	);
}

type Args = {
	open: boolean;
	port: string;
	help: boolean;
	version: boolean;
};

const args = mri<Args>(process.argv.slice(2), {
	boolean: ["open", "help", "version"],
	string: ["port"],
	alias: {
		port: "p",
		help: "h",
		version: "v",
	},
	default: {
		open: false,
		help: false,
		version: false,
	},
});

if (args.help) {
	console.info(
		`
Usage:
    start-slicemachine [options...]

Options:
    --open         Open Slice Machine automatically
    --port, -p     Specify the port on which to run Slice Machine
    --help, -h     Show help text
    --version, -v  Show version
`.trim(),
	);

	process.exit();
}

if (args.version) {
	console.info(pkg.version);

	process.exit();
}

let port: number | undefined;
if (args.port) {
	const parsedPort = Number.parseInt(args.port);

	if (Number.isNaN(parsedPort)) {
		console.info(`An invalid port number was provided: ${args.port}`);
	} else {
		port = parsedPort;
	}
}

import("./StartSliceMachineProcess").then(
	({ createStartSliceMachineProcess }) => {
		const startSliceMachineProcess = createStartSliceMachineProcess({
			open: args.open,
			port,
		});

		startSliceMachineProcess.run();
	},
);
